CREATE TABLE IF NOT EXISTS public.subscriptions (id uuid DEFAULT gen_random_uuid() PRIMARY KEY, organization_id uuid NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE, plan text NOT NULL DEFAULT 'TRIAL', status text NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('TRIALING','ACTIVE','PAST_DUE','CANCELED','PAUSED')), current_period_start date NOT NULL DEFAULT current_date, current_period_end date, provider text, provider_subscription_id text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (organization_id));